-- =============================================================================
--  Taiyabah Masjid
--  Migration 163: import the 2027 Salah timetable
--
--  WHY
--    The masjid's 2027 printed timetable (all twelve months, plus the
--    separate "2nd Jumma Times" sheet) was transcribed and loaded into
--    production directly through Supabase on 16 November 2026, because
--    save_prayer_year() refuses anyone who is not a verified admin signed
--    in through a real session — current_masjid() resolves from auth.uid(),
--    which a direct database connection does not have. This file is that
--    same data, committed so the repository has a record of it: until now,
--    no year's timetable data had ever been committed here at all — only
--    the schema and the functions that accept it (db/039_prayer_times.sql).
--    Every other year's timetable went in solely through the admin screen
--    at /times/ and left no trace in this repository.
--
--    Running this file again is harmless: it deletes any existing 2027 rows
--    for Taiyabah first, then re-inserts the same 365, so it can be used to
--    restore this exact timetable if 2027 is ever altered or cleared.
--
--  TWO THINGS IN THE SOURCE THAT ARE NOT A PLAIN TRANSCRIPTION
--
--    1. The printed sheet's 1st-6th June rows give Zil Hajj as "1447 AH".
--       That runs backward from Zil Qa'dah 1448 AH in May, and does not
--       square with the sheet's own "Islamic New Year 1449 - Sun 6th June
--       2027" callout five days later, which needs the year before it to
--       be 1448. Treated as a typo in the source and corrected to 1448 AH.
--
--    2. The separate "2nd Jumma Times" sheet stops at 24th December 2027.
--       31st December is also a Friday, one week past the sheet's own flat
--       weekly pattern (2nd April-29th October) and past its last four
--       printed December dates. The office confirmed 1:40pm for that date
--       when asked directly, rather than it being read off the PDF.
--
--  THE SHAPE OF THE DATA
--    One row per day: month, day, the Hijri date exactly as this project's
--    prayer_times rows already write it elsewhere ("D MonthName NNNN AH"),
--    then the ten HH:MM times and the jummah field, in the same column
--    order save_prayer_year()'s p_rows expects. jummah is empty except on
--    a Friday, where it is "<the day's own Zuhr jamaah time>,<that week's
--    2nd Jumma time>" -- confirmed against the live 2026 data before this
--    was written, since the printed grid's Friday Zuhr-jamaah column is the
--    FIRST Jumu'ah time and the separate sheet gives the second.
--
--  WHAT THIS DOES NOT DO
--    It does not touch save_prayer_year(), prayer_year(), or anything else
--    in db/039_prayer_times.sql. Separately from this import: that file is
--    now stale relative to production — prayer_times and prayer_years both
--    carry a masjid_id column there is no migration for, prayer_year() has
--    a (text, integer) overload not defined anywhere in this repository, and
--    save_prayer_year()'s live body scopes every write to current_masjid()
--    with no corresponding file either. That gap predates this migration
--    and is not this migration's to close.
-- =============================================================================

do $$
declare
  v_masjid uuid;
  v_n int;
begin
  select id into v_masjid from public.masjids where slug = 'taiyabah';
  if v_masjid is null then
    raise exception 'No masjid with slug ''taiyabah'' -- is this the right project?';
  end if;

  delete from public.prayer_times where masjid_id = v_masjid and year = 2027;

  insert into public.prayer_times
    (masjid_id, year, month, day, hijri, fajr_begins, fajr_jamaah, sunrise,
     zuhr_begins, zuhr_jamaah, asr_begins, asr_jamaah,
     maghrib, isha_begins, isha_jamaah, jummah)
  values
    (v_masjid, 2027, 1, 1, '23 Rajab 1448 AH', '06:36', '07:45', '08:26', '12:20', '12:45', '14:13', '14:45', '16:06', '17:48', '18:30', '12:45,13:40'),
